<h5 class="mb-1">Declaraciones juradas</h5><p class="text-muted small">La aceptación se registra con fecha, IP y una huella de integridad.</p>
<?php foreach($declaraciones as $d): ?><div class="card mb-2"><div class="card-body"><div class="form-check"><input class="form-check-input aceptar-declaracion" type="checkbox" id="dj<?= $d['tde_ide'] ?>" data-id="<?= $d['tde_ide'] ?>" <?= !empty($aceptadas[$d['tde_ide']])?'checked':'' ?> <?= !$editable?'disabled':'' ?>><label class="form-check-label" for="dj<?= $d['tde_ide'] ?>"><strong><?= esc($d['tde_nombre']) ?></strong><br><span class="text-muted small"><?= esc($d['tde_contenido']) ?></span></label></div></div></div><?php endforeach ?>
<?php if(!$declaraciones): ?><div class="alert alert-info">No hay declaraciones activas configuradas.</div><?php endif ?><script>$('.aceptar-declaracion').on('change',function(){const x=$(this);$.post('<?= base_url('seleccion/postulacion/inscripcion/declaracion/'.$convocatoriaId) ?>/'+x.data('id'),{acepta:x.is(':checked')?1:0}).done(r=>r.status?toastr.success(r.message):toastr.error(r.message)).fail(y=>{x.prop('checked',!x.is(':checked'));toastr.error(y.responseJSON?.message||'No se pudo registrar la aceptación')});});</script>
